using System.Text.Json;

namespace LiveCaptionsTranslator.Core.Tests;

/// <summary>
/// Loads <c>tests/fixtures/iflytek-golden.json</c>, which is generated by
/// <c>tools/generate-iflytek-golden.py</c> from the reference Python implementation.
/// Property paths may be dotted, e.g. <c>chunkCase.chunkBytes</c>.
/// </summary>
internal static class Golden
{
    private static readonly Lazy<JsonDocument> Document = new(() =>
        JsonDocument.Parse(File.ReadAllText(
            Path.Combine(AppContext.BaseDirectory, "fixtures", "iflytek-golden.json"))));

    public static JsonElement Root => Document.Value.RootElement;

    public static IEnumerable<JsonElement> Items(string property)
    {
        foreach (var item in Root.GetProperty(property).EnumerateArray())
            yield return item;
    }

    public static JsonElement Resolve(string path)
    {
        var element = Root;
        foreach (string part in path.Split('.'))
            element = element.GetProperty(part);

        return element;
    }

    public static string String(string path) => Resolve(path).GetString()!;

    public static int Int(string path) => Resolve(path).GetInt32();

    public static byte[] Bytes(string path) => Convert.FromBase64String(String(path));
}
